        term accept-snmp {
            from {
                source-prefix-list {
                    snmp-servers-ipv4;
                }
                destination-prefix-list {
                    router-addresses-ipv4;
                }
                protocol udp;
                destination-port snmp;
            }
            then {
                policer policer-1m;
                accept;
            }
        }

