                    msdp-peers-ipv6;
                }
                next-header tcp;
                destination-port msdp;
            }
            then accept;
        }
        term 2 {
            from {
                source-prefix-list {
                    msdp-peers-ipv6;
                }
                next-header tcp;
                source-port msdp;
            }
            then accept;
