    }
}
ldp {
    interface .;
}
-OR-
isis {
    interface . {
        ldp-synchronization {
            hold-time 10;
        }
    }
    level 1 authentication-key-chain ;
    level 2 authentication-key-chain ;
}
mpls {
    interface .;
}

